const articles = $input.all().map(item => ({
  title: item.json.title,
  summary: (item.json.summary || "").substring(0, 300),
  link: item.json.link
}));

return [
  {
    json: {
      articles
    }
  }
];

const posts = [
  $json.Tweet_1_Text,
  $json.Tweet_2_Text,
  $json.Tweet_3_Text,
  $json.Tweet_4_Text,
  $json.Tweet_5_Text,
].filter(post => post && post.trim() !== "");

return [{
  json: {
    ...$json,
    posts
  }
}];

const tweet = $('Parse Posts JSON').item.json.Tweet_3_Text;

return [{
  json: {
    length: tweet.length,
    tweet
  }
}];

